import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 override func tearDown(){XCUIDevice.shared.orientation = .portrait;super.tearDown()}
 func testSupportedPortraitLockAndKeyboardCloseReopenKeepsUnsentText() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Profile, tab, 5 of 5");tap(app,"Ask Fancy");tap(app,"Continue conversation");let q=app.textViews["Ask Fancy a question"];XCTAssertTrue(q.waitForExistence(timeout:12));q.tap();for c in "QAROT82"{q.typeText(String(c));Thread.sleep(forTimeInterval:0.15)};XCTAssertEqual(q.value as? String,"QAROT82");let keyboard=app.keyboards.firstMatch;XCTAssertTrue(keyboard.waitForExistence(timeout:10));XCUIDevice.shared.orientation = .landscapeLeft;let rotated=XCTNSPredicateExpectation(predicate:NSPredicate{_,_ in XCUIDevice.shared.orientation == .landscapeLeft},object:nil);XCTAssertEqual(XCTWaiter.wait(for:[rotated],timeout:12),.completed);XCTAssertLessThan(app.frame.width,app.frame.height,"Official iPhone app supports portrait only; do not force unsupported landscape layout.");let ask=app.buttons["Ask"];var scrolls=0;while !ask.isHittable && scrolls<3{app.scrollViews.element(boundBy:app.scrollViews.count-1).swipeUp();scrolls+=1};XCTAssertTrue(app.keyboards.firstMatch.exists);XCTAssertTrue(ask.isHittable,app.debugDescription);XCTAssertTrue(app.buttons["Close"].isHittable);XCTAssertLessThanOrEqual(ask.frame.maxY,keyboard.frame.minY+1);print("QA_NATIVE82_PORTRAIT_LOCK physicalDeviceLandscape=true app=\(app.frame) keyboard=\(keyboard.frame) ask=\(ask.frame) naturalScrolls=\(scrolls)\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native82-supported-portrait-lock-keyboard";a.lifetime = .keepAlways;add(a);tap(app,"Close");let closed=XCTNSPredicateExpectation(predicate:NSPredicate{_,_ in !app.keyboards.firstMatch.exists},object:nil);XCTAssertEqual(XCTWaiter.wait(for:[closed],timeout:12),.completed);tap(app,"Ask Fancy");tap(app,"Continue conversation");XCTAssertTrue(q.waitForExistence(timeout:12));XCTAssertEqual(q.value as? String,"QAROT82");print("QA_NATIVE82_CLOSE_REOPEN_UNSENT_RETAINED\n"+app.debugDescription);let b=XCTAttachment(screenshot:app.screenshot());b.name="native82-close-reopen-unsent";b.lifetime = .keepAlways;add(b)
 }
}
